final List<Doa> doaList = [
  Doa(id: 1, title: 'Doa Sebelum Makan', category: 'Harian', arabic: 'اَللّٰهُمَّ بَارِكْ لَنَا فِيْمَا رَزَقْتَنَا وَقِنَا عَذَابَ النَّارِ', latin: 'Allahumma baarik lanaa fiimaa razaqtanaa wa qinaa \'adzaaban naar', translation: 'Ya Allah, berkahilah kami dalam rezeki yang telah Engkau berikan kepada kami dan peliharalah kami dari siksa api neraka.', source: 'HR. Ibnu Sunni'),
  Doa(id: 2, title: 'Doa Sesudah Makan', category: 'Harian', arabic: 'اَلْحَمْدُ لِلّٰهِ الَّذِيْ أَطْعَمَنَا وَسَقَانَا وَجَعَلَنَا مُسْلِمِيْنَ', latin: 'Alhamdulillaahil ladzii ath\'amanaa wa saqaanaa wa ja\'alanaa muslimiin', translation: 'Segala puji bagi Allah yang telah memberi kami makan dan minum serta menjadikan kami sebagai orang-orang muslim.', source: 'HR. Abu Dawud & Tirmidzi'),
  Doa(id: 3, title: 'Doa Sebelum Tidur', category: 'Harian', arabic: 'بِاسْمِكَ اللّٰهُمَّ أَحْيَا وَأَمُوْتُ', latin: 'Bismikallaahumma ahyaa wa amuut', translation: 'Dengan menyebut nama-Mu ya Allah, aku hidup dan aku mati.', source: 'HR. Bukhari & Muslim'),
  Doa(id: 4, title: 'Doa Bangun Tidur', category: 'Harian', arabic: 'اَلْحَمْدُ لِلّٰهِ الَّذِيْ أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُوْرُ', latin: 'Alhamdulillaahil ladzii ahyaanaa ba\'da maa amaatanaa wa ilaihin nusyuur', translation: 'Segala puji bagi Allah yang telah menghidupkan kami sesudah mematikan kami dan kepada-Nya lah kami dibangkitkan.', source: 'HR. Bukhari'),
  Doa(id: 5, title: 'Doa Keluar Rumah', category: 'Harian', arabic: 'بِسْمِ اللّٰهِ تَوَكَّلْتُ عَلَى اللّٰهِ لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللّٰهِ', latin: 'Bismillaahi tawakkaltu \'alallaahi laa haula walaa quwwata illaa billaah', translation: 'Dengan nama Allah, aku bertawakal kepada Allah. Tiada daya dan kekuatan kecuali dengan pertolongan Allah.', source: 'HR. Abu Dawud & Tirmidzi'),
  Doa(id: 6, title: 'Doa Masuk Rumah', category: 'Harian', arabic: 'بِسْمِ اللّٰهِ وَلَجْنَا وَبِسْمِ اللّٰهِ خَرَجْنَا وَعَلَى اللّٰهِ رَبِّنَا تَوَكَّلْنَا', latin: 'Bismillaahi walajnaa wa bismillaahi kharajnaa wa \'alaaLlaahi rabbinaa tawakkalnaa', translation: 'Dengan nama Allah kami masuk dan dengan nama Allah kami keluar dan kepada Allah Tuhan kami, kami bertawakal.', source: 'HR. Abu Dawud'),
  Doa(id: 7, title: 'Doa Masuk Masjid', category: 'Ibadah', arabic: 'اَللّٰهُمَّ افْتَحْ لِيْ أَبْوَابَ رَحْمَتِكَ', latin: 'Allaahummaf tahlii abwaaba rahmatik', translation: 'Ya Allah, bukakanlah untukku pintu-pintu rahmat-Mu.', source: 'HR. Muslim'),
  Doa(id: 8, title: 'Doa Keluar Masjid', category: 'Ibadah', arabic: 'اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ مِنْ فَضْلِكَ', latin: 'Allaahumma innii as-aluka min fadlik', translation: 'Ya Allah, sesungguhnya aku memohon kepada-Mu dari karunia-Mu.', source: 'HR. Muslim'),
  Doa(id: 9, title: 'Doa Masuk Kamar Mandi', category: 'Harian', arabic: 'اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ', latin: 'Allaahumma innii a\'uudzubika minal khubutsi wal khabaa-its', translation: 'Ya Allah, sesungguhnya aku berlindung kepada-Mu dari godaan setan laki-laki dan setan perempuan.', source: 'HR. Bukhari & Muslim'),
  Doa(id: 10, title: 'Doa Keluar Kamar Mandi', category: 'Harian', arabic: 'غُفْرَانَكَ', latin: 'Ghufraanak', translation: 'Aku memohon ampunan-Mu.', source: 'HR. Abu Dawud & Tirmidzi'),
  Doa(id: 11, title: 'Doa Bercermin', category: 'Harian', arabic: 'اَللّٰهُمَّ كَمَا حَسَّنْتَ خَلْقِيْ فَحَسِّنْ خُلُقِيْ', latin: 'Allaahumma kamaa hassanta khalqii fahassin khuluqii', translation: 'Ya Allah, sebagaimana Engkau telah memperindah kejadianku maka perindahlah akhlakku.', source: 'HR. Ahmad'),
  Doa(id: 12, title: 'Doa Naik Kendaraan', category: 'Perjalanan', arabic: 'سُبْحَانَ الَّذِيْ سَخَّرَ لَنَا هٰذَا وَمَا كُنَّا لَهُ مُقْرِنِيْنَ وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُوْنَ', latin: 'Subhaanal ladzii sakhkhara lanaa haadzaa wa maa kunnaa lahuu muqriniin, wa innaa ilaa rabbinaa lamunqalibuun', translation: 'Maha Suci Allah yang telah menundukkan semua ini bagi kami padahal kami sebelumnya tidak mampu menguasainya. Dan sesungguhnya kami akan kembali kepada Tuhan kami.', source: 'QS. Az-Zukhruf: 13-14'),
  Doa(id: 13, title: 'Doa Bepergian', category: 'Perjalanan', arabic: 'اَللّٰهُمَّ إِنَّا نَسْأَلُكَ فِيْ سَفَرِنَا هٰذَا الْبِرَّ وَالتَّقْوٰى وَمِنَ الْعَمَلِ مَا تَرْضٰى', latin: 'Allaahumma innaa nas-aluka fii safarinaa haadzal birra wat taqwaa wa minal \'amali maa tardhaa', translation: 'Ya Allah, sesungguhnya kami memohon kepada-Mu dalam perjalanan kami ini kebaikan, ketakwaan, dan amalan yang Engkau ridhai.', source: 'HR. Muslim'),
  Doa(id: 14, title: 'Doa Memohon Ilmu', category: 'Belajar', arabic: 'رَبِّ زِدْنِيْ عِلْمًا وَارْزُقْنِيْ فَهْمًا', latin: 'Rabbi zidnii \'ilman warzuqnii fahman', translation: 'Ya Tuhanku, tambahkanlah ilmu kepadaku dan berikanlah aku pemahaman.', source: 'QS. Taha: 114'),
  Doa(id: 15, title: 'Doa Sebelum Belajar', category: 'Belajar', arabic: 'اَللّٰهُمَّ افْتَحْ عَلَيْنَا حِكْمَتَكَ وَانْشُرْ عَلَيْنَا رَحْمَتَكَ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ', latin: 'Allaahummaf tah \'alainaa hikmataka wan syur \'alainaa rahmataka yaa dzal jalaali wal ikraam', translation: 'Ya Allah, bukakanlah hikmah-Mu kepada kami dan curahkanlah rahmat-Mu kepada kami, wahai Tuhan Yang Maha Agung lagi Maha Mulia.', source: 'Kitab Ta\'lim Muta\'allim'),
  Doa(id: 16, title: 'Doa Memohon Rezeki', category: 'Rezeki', arabic: 'اَللّٰهُمَّ اكْفِنِيْ بِحَلَالِكَ عَنْ حَرَامِكَ وَأَغْنِنِيْ بِفَضْلِكَ عَمَّنْ سِوَاكَ', latin: 'Allaahummak finii bihalaalika \'an haraamika wa aghninii bifadhlika \'amman siwaak', translation: 'Ya Allah, cukupkanlah aku dengan rezeki yang halal sehingga aku tidak memerlukan yang haram. Dan kayakanlah aku dengan karunia-Mu sehingga aku tidak memerlukan siapapun selain-Mu.', source: 'HR. Tirmidzi'),
  Doa(id: 17, title: 'Doa Memohon Kesehatan', category: 'Kesehatan', arabic: 'اَللّٰهُمَّ عَافِنِيْ فِيْ بَدَنِيْ اَللّٰهُمَّ عَافِنِيْ فِيْ سَمْعِيْ اَللّٰهُمَّ عَافِنِيْ فِيْ بَصَرِيْ', latin: 'Allaahumma \'aafinii fii badanii, Allaahumma \'aafinii fii sam\'ii, Allaahumma \'aafinii fii bashorii', translation: 'Ya Allah, sehatkan tubuhku. Ya Allah, sehatkan pendengaranku. Ya Allah, sehatkan penglihatanku.', source: 'HR. Abu Dawud'),
  Doa(id: 18, title: 'Doa Memohon Keselamatan', category: 'Keselamatan', arabic: 'اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ', latin: 'Allaahumma innii as-alukal \'aafiyata fid dunyaa wal aakhirah', translation: 'Ya Allah, sesungguhnya aku memohon kepada-Mu keselamatan di dunia dan akhirat.', source: 'HR. Abu Dawud & Tirmidzi'),
  Doa(id: 19, title: 'Doa untuk Kedua Orang Tua', category: 'Keluarga', arabic: 'رَبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِيْ صَغِيْرًا', latin: 'Rabbir hamhumaa kamaa rabbayaanii shagiiraa', translation: 'Ya Tuhanku, sayangilah keduanya sebagaimana mereka berdua telah mendidikku waktu kecil.', source: 'QS. Al-Isra: 24'),
  Doa(id: 20, title: 'Doa Memohon Ampunan', category: 'Taubat', arabic: 'رَبَّنَا ظَلَمْنَا أَنْفُسَنَا وَإِنْ لَمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُوْنَنَّ مِنَ الْخَاسِرِيْنَ', latin: 'Rabbanaa zhalamnaa anfusanaa wa il lam taghfir lanaa wa tarhamnaa lanakuunanna minal khaasiriin', translation: 'Ya Tuhan kami, kami telah menganiaya diri kami sendiri. Dan jika Engkau tidak mengampuni kami serta merahmati kami, niscaya kami termasuk orang-orang yang merugi.', source: 'QS. Al-A\'raf: 23'),
  Doa(id: 21, title: 'Doa Sayyidul Istighfar', category: 'Taubat', arabic: 'اَللّٰهُمَّ أَنْتَ رَبِّيْ لَا إِلٰهَ إِلَّا أَنْتَ خَلَقْتَنِيْ وَأَنَا عَبْدُكَ وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ أَعُوْذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ أَبُوْءُ لَكَ بِنِعْمَتِكَ عَلَيَّ وَأَبُوْءُ بِذَنْبِيْ فَاغْفِرْ لِيْ فَإِنَّهُ لَا يَغْفِرُ الذُّنُوْبَ إِلَّا أَنْتَ', latin: 'Allaahumma anta rabbii laa ilaaha illaa anta, khalaqtanii wa ana \'abduka, wa ana \'alaa \'ahdika wa wa\'dika mas tatha\'tu, a\'uudzu bika min syarri maa shana\'tu, abuu-u laka bi ni\'matika \'alayya wa abuu-u bi dzanbii, faghfirlii fa innahu laa yaghfirudz dzunuuba illaa anta', translation: 'Ya Allah, Engkau adalah Tuhanku, tidak ada tuhan yang berhak disembah selain Engkau. Engkau menciptakanku dan aku adalah hamba-Mu. Aku berpegang pada perjanjian dan janji-Mu semampuku. Aku berlindung kepada-Mu dari keburukan yang kuperbuat. Aku mengakui nikmat-Mu kepadaku dan aku mengakui dosaku. Maka ampunilah aku, karena sesungguhnya tidak ada yang mengampuni dosa selain Engkau.', source: 'HR. Bukhari'),
  Doa(id: 22, title: 'Doa Memakai Pakaian', category: 'Harian', arabic: 'اَلْحَمْدُ لِلّٰهِ الَّذِيْ كَسَانِيْ هٰذَا الثَّوْبَ وَرَزَقَنِيْهِ مِنْ غَيْرِ حَوْلٍ مِنِّيْ وَلَا قُوَّةٍ', latin: 'Alhamdulillaahil ladzii kasaanii haadzats tsauba wa razaqaniihi min ghairi haulin minnii wa laa quwwatin', translation: 'Segala puji bagi Allah yang telah memberiku pakaian ini dan memberikan rezeki kepadaku tanpa daya dan kekuatan dariku.', source: 'HR. Abu Dawud & Tirmidzi'),
  Doa(id: 23, title: 'Doa Ketika Hujan', category: 'Alam', arabic: 'اَللّٰهُمَّ صَيِّبًا نَافِعًا', latin: 'Allaahumma shayyiban naafi\'an', translation: 'Ya Allah, jadikanlah hujan ini bermanfaat.', source: 'HR. Bukhari'),
  Doa(id: 24, title: 'Doa Pagi Hari', category: 'Harian', arabic: 'أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلّٰهِ وَالْحَمْدُ لِلّٰهِ لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَرِيْكَ لَهُ', latin: 'Ashbahnaa wa ashbahal mulku lillaah, walhamdulillaah, laa ilaaha illallaahu wahdahu laa syariika lah', translation: 'Kami memasuki waktu pagi dan kerajaan hanya milik Allah. Segala puji bagi Allah. Tiada tuhan selain Allah Yang Maha Esa, tiada sekutu bagi-Nya.', source: 'HR. Muslim'),
  Doa(id: 25, title: 'Doa Sore Hari', category: 'Harian', arabic: 'أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلّٰهِ وَالْحَمْدُ لِلّٰهِ لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَرِيْكَ لَهُ', latin: 'Amsainaa wa amsal mulku lillaah, walhamdulillaah, laa ilaaha illallaahu wahdahu laa syariika lah', translation: 'Kami memasuki waktu sore dan kerajaan hanya milik Allah. Segala puji bagi Allah. Tiada tuhan selain Allah Yang Maha Esa, tiada sekutu bagi-Nya.', source: 'HR. Muslim'),
  Doa(id: 26, title: 'Doa Pernikahan', category: 'Keluarga', arabic: 'بَارَكَ اللّٰهُ لَكَ وَبَارَكَ عَلَيْكَ وَجَمَعَ بَيْنَكُمَا فِيْ خَيْرٍ', latin: 'Baarakallahu laka wa baaraka \'alaika wa jama\'a bainakumaa fii khair', translation: 'Semoga Allah memberkahimu dan memberkahi atasmu dan mengumpulkan kalian berdua dalam kebaikan.', source: 'HR. Abu Dawud & Tirmidzi'),
  Doa(id: 27, title: 'Doa Menjenguk Orang Sakit', category: 'Sosial', arabic: 'اَللّٰهُمَّ رَبَّ النَّاسِ أَذْهِبِ الْبَأْسَ اشْفِ أَنْتَ الشَّافِيْ لَا شِفَاءَ إِلَّا شِفَاؤُكَ شِفَاءً لَا يُغَادِرُ سَقَمًا', latin: 'Allaahumma rabban naas, adzhihbil ba\'sa, isyfi antasy syaafii, laa syifaa-a illaa syifaa-uka, syifaa-an laa yughaadiru saqaman', translation: 'Ya Allah, Tuhan seluruh manusia, hilangkanlah penyakit ini, sembuhkanlah, Engkaulah Yang Maha Menyembuhkan. Tidak ada kesembuhan kecuali kesembuhan dari-Mu, kesembuhan yang tidak menyisakan penyakit.', source: 'HR. Bukhari & Muslim'),
  Doa(id: 28, title: 'Doa Kebaikan Dunia Akhirat', category: 'Umum', arabic: 'رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ', latin: 'Rabbanaa aatinaa fid dunyaa hasanatan wa fil aakhirati hasanatan wa qinaa \'adzaaban naar', translation: 'Ya Tuhan kami, berilah kami kebaikan di dunia dan kebaikan di akhirat, dan peliharalah kami dari siksa api neraka.', source: 'QS. Al-Baqarah: 201'),
  Doa(id: 29, title: 'Doa Sebelum Wudhu', category: 'Ibadah', arabic: 'بِسْمِ اللّٰهِ', latin: 'Bismillaah', translation: 'Dengan nama Allah.', source: 'HR. Abu Dawud'),
  Doa(id: 30, title: 'Doa Sesudah Wudhu', category: 'Ibadah', arabic: 'أَشْهَدُ أَنْ لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَرِيْكَ لَهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُوْلُهُ', latin: 'Asyhadu an laa ilaaha illallaahu wahdahu laa syariika lahu wa asyhadu anna Muhammadan \'abduhu wa rasuuluh', translation: 'Aku bersaksi bahwa tiada tuhan selain Allah Yang Maha Esa, tiada sekutu bagi-Nya. Dan aku bersaksi bahwa Muhammad adalah hamba dan utusan-Nya.', source: 'HR. Muslim'),
];

